pub fn is_prime(n: i8) -> bool {
    // Handle all values < 2 (including negatives) as non-prime by definition.
    if n < 2 {
        return false;
    }

    // Work in a wider type to avoid any risk of overflow in arithmetic/termination measure.
    let nn: i16 = n as i16;

    // Candidate divisor starts at 2 and increases by 1.
    // Loop condition matches: check all k with 2 <= k < n.
    let mut k: i16 = 2;

    while k < nn {
        // If a divisor is found, immediately return false.
        if nn % k == 0 {
            return false;
        }

        // Termination measure example (conceptual): nn - k
        // This strictly decreases because k increments by 1 each iteration and k < nn here.
        k += 1;
    }

    // No divisors found in [2, n), so n is prime under the given definition.
    true
}